// PESCA — Parse filtros e buscar CNPJs via Casa dos Dados API
const body = $input.first().json.body || $input.first().json;
const cnaeCodes = body.cnaeCodes || [];
const states = body.states || [];
const capitalMin = parseInt(body.capitalMin) || 0;
const capitalMax = parseInt(body.capitalMax) || 10000000;
const excludeMei = body.excludeMei !== false;
const targetCount = parseInt(body.targetCount) || 150;

const allCompanies = [];
const seenCnpjs = new Set();

// Iterar por cada CNAE para maximizar resultados
for (const cnae of cnaeCodes) {
  if (allCompanies.length >= targetCount) break;

  let page = 1;
  const maxPages = 10;

  while (page <= maxPages && allCompanies.length < targetCount) {
    try {
      const payload = {
        query: {
          termo: [],
          atividade_principal: [cnae],
          natureza_juridica: [],
          uf: states.length > 0 ? states : [],
          municipio: [],
          situacao_cadastral: 'ATIVA'
        },
        range_query: {
          capital_social: { gte: capitalMin, lte: capitalMax }
        },
        extras: {
          somente_mei: false,
          excluir_mei: excludeMei,
          com_email: false,
          incluir_atividade_secundaria: false,
          com_contato_telefonico: true
        },
        page: page
      };

      const response = await fetch('https://api.casadosdados.com.br/v2/public/cnpj/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        if (response.status === 429) {
          // Rate limit — esperar 3s e tentar de novo
          await new Promise(r => setTimeout(r, 3000));
          continue;
        }
        break;
      }

      const data = await response.json();
      const companies = data?.data?.cnpj || [];

      if (companies.length === 0) break;

      for (const company of companies) {
        const cleanCnpj = (company.cnpj || '').replace(/\D/g, '');
        if (!cleanCnpj || seenCnpjs.has(cleanCnpj)) continue;
        seenCnpjs.add(cleanCnpj);

        allCompanies.push({
          cnpj: cleanCnpj,
          razao_social: company.razao_social || '',
          nome_fantasia: company.nome_fantasia || '',
          cnae_fiscal_descricao: company.cnae_fiscal_descricao || '',
          cnae_fiscal: company.cnae_fiscal || '',
          uf: company.uf || '',
          municipio: company.municipio || '',
          logradouro: company.logradouro || '',
          numero: company.numero || '',
          bairro: company.bairro || '',
          capital_social: company.capital_social || 0,
          porte: company.porte || '',
          data_inicio_atividade: company.data_inicio_atividade || '',
          telefone1: company.telefone1 || company.ddd_telefone_1 || '',
          telefone2: company.telefone2 || company.ddd_telefone_2 || '',
          email: company.email || company.correio_eletronico || '',
          qsa: (company.qsa || []).map(s => ({
            nome_socio: s.nome_socio || s.nome || '',
            qualificacao_socio: s.qualificacao_socio || s.qual || ''
          }))
        });
      }

      page++;
      // Delay entre paginas
      await new Promise(r => setTimeout(r, 500));
    } catch (err) {
      // Erro de rede — tentar proximo CNAE
      break;
    }
  }
}

return [{ json: { companies: allCompanies, total: allCompanies.length } }];
